export const PROMISED_LAND_PLACES: BiblicalPlace[] = SEEDS.map(seed => {
  const gridReference = seed.mapReferences.join(', ');
  const sourceNote =
    seed.coordinatePrecision === 'approximate'
      ? 'Position approximative reportée depuis la carte ; elle ne doit pas être interprétée comme une identification archéologique certaine.'
      : seed.coordinatePrecision === 'representative'
        ? 'Le point représente le tracé ou le centre de l’entité naturelle et non toute son étendue.'
        : `Identification moderne proposée : ${seed.modernName}.`;

  return {
    id: seed.id,
    name: seed.name,
    alternateNames: seed.alternateNames,
    coordinates: seed.coordinates,
    description: CATEGORY_DESCRIPTIONS[seed.mapCategory],
    biblicalReferences: seed.biblicalReferences,
    documentaryReferences: [
      `Carte « La Terre promise », grille ${gridReference}`
    ],
    sources: [
      {
        id: 'carte-terre-promise',
        label: 'Carte « La Terre promise » et encart « Les environs de Jérusalem »',
        citation: `Référence de grille : ${gridReference}`
      },
      ...(seed.ancientId
        ? [
            {
              id: 'openbible-geocoding',
              label: 'OpenBible.info Bible Geocoding Data (CC BY 4.0)',
              url: 'https://github.com/openbibleinfo/Bible-Geocoding-Data',
              citation: `${seed.ancientName} — ${seed.ancientId}`
            }
          ]
        : [])
    ],
    certainty: seed.certainty,
    notes: sourceNote,
    lastVerified: '2026-07-24',
    category: CATEGORY_LABELS[seed.mapCategory],
    mapCategory: seed.mapCategory,
    mapReferences: seed.mapReferences,
    coordinatePrecision: seed.coordinatePrecision
  };
});
